import{_ as t,o,c as a,a4 as i}from"./chunks/framework.YC5CMuPM.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1790862341000}'),r={name:"changelog.md"};function n(d,e,s,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p><strong>What changed on this site, newest first, and which JUCE version the content describes.</strong> Entries come from this repository&#39;s git history, so each one links to its commit.</p><div class="info custom-block"><p class="custom-block-title">Current content baseline</p><p>The pages describe <strong>JUCE 9.0.3</strong>, read from <code>JUCE_MAJOR_VERSION</code>, <code>JUCE_MINOR_VERSION</code> and <code>JUCE_BUILDNUMBER</code> in <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_core/system/juce_StandardHeader.h" target="_blank" rel="noreferrer"><code>juce_StandardHeader.h</code></a>. The module map and module table regenerate from the headers on every build, so they follow the checked-out version. Hand-written pages do not, so check the JUCE release notes below when you upgrade.</p></div><h2 id="this-site" tabindex="-1">This site <a class="header-anchor" href="#this-site" aria-label="Permalink to &quot;This site&quot;">​</a></h2><h3 id="_2026-10-01-box2d-tutorials" tabindex="-1">2026-10-01: Box2D tutorials <a class="header-anchor" href="#_2026-10-01-box2d-tutorials" aria-label="Permalink to &quot;2026-10-01: Box2D tutorials&quot;">​</a></h3><ul><li>Tutorials: added three original guides to the Tutorials section, with sidebar labels. They are Markdown in <code>docs/tutorials/</code>, so the build picks them up. The home page and About page no longer call every guide a condensed adaptation of a juce.com tutorial. <ul><li>15, Physics as a musical instrument: the bundled <code>juce_box2d</code> module, turning contact callbacks into notes, the threading design, and why the bundled Box2D is old and what it lacks. Companion app: <code>examples/Box2DMusic</code>, added to the examples build. (<a href="https://github.com/andrewh/JUCE/commit/8aa43908" target="_blank" rel="noreferrer"><code>8aa43908</code></a>, <a href="https://github.com/andrewh/JUCE/commit/6e30cdf7" target="_blank" rel="noreferrer"><code>6e30cdf7</code></a>)</li><li>16, Integrating Box2D v3: fetching v3.1.1 with CMake <code>FetchContent</code>, ids instead of pointers, hit and sensor events. Companion app: <code>MusicV3</code> in <code>examples/Box2DAudioV3</code>. (<a href="https://github.com/andrewh/JUCE/commit/8748cf59" target="_blank" rel="noreferrer"><code>8748cf59</code></a>)</li><li>17, A physical audio engine: modal synthesis driven by contact events, rolling noise, voice management. Companion app: <code>Modal</code> in <code>examples/Box2DAudioV3</code>. (<a href="https://github.com/andrewh/JUCE/commit/8748cf59" target="_blank" rel="noreferrer"><code>8748cf59</code></a>)</li></ul></li><li><code>examples/Box2DAudioV3</code> is a separate CMake project that downloads Box2D, so ordinary JUCE builds do not need network access.</li></ul><h3 id="_2026-09-29-copy-review-and-tutorials" tabindex="-1">2026-09-29: Copy review and tutorials <a class="header-anchor" href="#_2026-09-29-copy-review-and-tutorials" aria-label="Permalink to &quot;2026-09-29: Copy review and tutorials&quot;">​</a></h3><ul><li>History: fixed the opening sentence of the lede.</li><li>About this site: corrected the hosting description (the site is deployed by the Pages workflow, not by serving <code>docs/</code>) and the publishing steps.</li><li>Tutorials: added fourteen condensed guides under a new Tutorials section (nav item, sidebar, and home page entry). They are generated at build time from <code>docs/tutorials/</code>, so the Markdown stays readable on GitHub, and they credit the ISC-licensed JUCE tutorials they adapt.</li><li>Rebuilt the static copy in <code>docs/</code>, which was missing the API reference nav entry and this changelog.</li></ul><h3 id="_2026-09-29-sources-and-changelog" tabindex="-1">2026-09-29: Sources and changelog <a class="header-anchor" href="#_2026-09-29-sources-and-changelog" aria-label="Permalink to &quot;2026-09-29: Sources and changelog&quot;">​</a></h3><ul><li>Added this changelog.</li><li>Added numbered source footnotes and a <strong>Sources</strong> section to the guide and reference pages. Sources are repository files (<code>README.md</code>, <code>LICENSE.md</code>, <code>CHANGE_LIST.md</code>, <code>docs/</code>, module headers) or public web pages, with retrieval dates for web pages.</li><li>Corrected or removed claims that could not be sourced: <ul><li>History: JUCE&#39;s first public release is now 2004, ROLI&#39;s acquisition is November 2014, and PACE&#39;s is April 2020. The earlier &quot;early 2000s&quot; and &quot;mid 2000s&quot; dates are gone.</li><li>History: removed the statements about the original licence, about JUCE 2 introducing modules, about the Audio Developer Conference growing out of the JUCE Summit, and about ROLI investing in documentation and community. None had a source.</li><li>History: the AGPLv3 move is now tied to the <code>LICENSE.md</code> files at tags 7.0.12 (GPLv3) and 8.0.0 (AGPLv3).</li><li>What is JUCE: replaced the unsourced &quot;who uses it&quot; paragraph, and added a not-legal-advice note to the licensing section.</li><li>Glossary and Anatomy of a plug-in: removed &quot;AUv3 is sandboxed and the only plug-in format on iOS&quot;, &quot;LV2 is popular on Linux&quot;, and the AbstractFifo &quot;single-producer, single-consumer&quot; wording (the header says single-reader, single-writer).</li><li>Build systems: removed the &quot;template wizard&quot; and &quot;most new projects and tutorials use CMake&quot; claims.</li></ul></li><li>Added a &quot;Sources and accuracy&quot; section to <a href="./about.html">About this site</a>.</li><li>Footer: dropped the company name and shortened the licence line to a pointer to <a href="https://github.com/juce-framework/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer"><code>LICENSE.md</code></a>, which holds the licence scope (modules AGPLv3 or commercial, examples ISC, third-party code under its own terms).</li></ul><h3 id="_2026-09-28-ci-publishing" tabindex="-1">2026-09-28: CI publishing <a class="header-anchor" href="#_2026-09-28-ci-publishing" aria-label="Permalink to &quot;2026-09-28: CI publishing&quot;">​</a></h3><ul><li>Added a GitHub Pages workflow that runs Doxygen and the VitePress build, and stopped <code>npm run deploy</code> copying the roughly 150 MB <code>api/</code> output into <code>docs/</code>. (<a href="https://github.com/andrewh/JUCE/commit/a724f0ca" target="_blank" rel="noreferrer"><code>a724f0c</code></a>)</li></ul><h3 id="_2026-09-28-api-reference" tabindex="-1">2026-09-28: API reference <a class="header-anchor" href="#_2026-09-28-api-reference" aria-label="Permalink to &quot;2026-09-28: API reference&quot;">​</a></h3><ul><li>Embedded a themed Doxygen API reference, linked class names in inline code to their Doxygen pages, and added an &quot;API reference&quot; nav entry. (<a href="https://github.com/andrewh/JUCE/commit/8311f356" target="_blank" rel="noreferrer"><code>8311f35</code></a>)</li></ul><h3 id="_2026-09-28-instrument-panel-theme" tabindex="-1">2026-09-28: Instrument-panel theme <a class="header-anchor" href="#_2026-09-28-instrument-panel-theme" aria-label="Permalink to &quot;2026-09-28: Instrument-panel theme&quot;">​</a></h3><ul><li>Restyled the site with a new palette, type, a live oscilloscope hero, and matching Mermaid, code, and table styling. (<a href="https://github.com/andrewh/JUCE/commit/73eb9b49" target="_blank" rel="noreferrer"><code>73eb9b4</code></a>)</li></ul><h3 id="_2026-09-28-initial-site" tabindex="-1">2026-09-28: Initial site <a class="header-anchor" href="#_2026-09-28-initial-site" aria-label="Permalink to &quot;2026-09-28: Initial site&quot;">​</a></h3><ul><li>Added the VitePress learning site: overview, architecture, core concepts, plug-in anatomy, build systems, history, modules reference, glossary, learning path, and an interactive module dependency graph. (<a href="https://github.com/andrewh/JUCE/commit/74ac78f8" target="_blank" rel="noreferrer"><code>74ac78f</code></a>)</li></ul><h2 id="juce-releases-in-this-checkout" tabindex="-1">JUCE releases in this checkout <a class="header-anchor" href="#juce-releases-in-this-checkout" aria-label="Permalink to &quot;JUCE releases in this checkout&quot;">​</a></h2><p>Headline changes, condensed from <a href="https://github.com/juce-framework/JUCE/blob/master/CHANGE_LIST.md" target="_blank" rel="noreferrer"><code>CHANGE_LIST.md</code></a>. Release dates are those of the &quot;JUCE version x.y.z&quot; commits in this repository&#39;s git history. For anything that can break your code, read <a href="https://github.com/juce-framework/JUCE/blob/master/BREAKING_CHANGES.md" target="_blank" rel="noreferrer"><code>BREAKING_CHANGES.md</code></a>.</p><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Headlines</th></tr></thead><tbody><tr><td>9.0.3</td><td>2026-09-28</td><td>Opus and WebP support; Windows MIDI Services preview 7 API; ALSA, window focus, and OpenGLFrameBuffer fixes; recursive LV2 scanning. Breaking: <code>SystemStats::isOperatingSystem64Bit()</code> now reports the OS rather than the process.</td></tr><tr><td>9.0.2</td><td>2026-09-07</td><td><code>MP3AudioFormat</code> enabled by default; OpenGL performance; CoreAudio and VST3 hosting fixes; <code>SECURITY.md</code> and a software bill of materials. Breaking: <code>ThreadPool::addJob</code> accepts one callable type returning <code>void</code> or <code>ThreadPoolJob::JobStatus</code>.</td></tr><tr><td>9.0.1</td><td>2026-08-10</td><td>TypeScript npm package for WebView integration; protection against malformed <code>AudioFormat</code> input.</td></tr><tr><td>9.0.0</td><td>2026-07-21</td><td>New SVG parser, variable fonts, new macOS CoreAudio implementation, faster software renderer, OpenGL ES on Linux, better multi-touch, CMake improvements for headless builds.</td></tr></tbody></table><p>Older releases are covered in <a href="./guide/history.html">History</a>.</p><h2 id="how-this-page-is-maintained" tabindex="-1">How this page is maintained <a class="header-anchor" href="#how-this-page-is-maintained" aria-label="Permalink to &quot;How this page is maintained&quot;">​</a></h2><ul><li>Add an entry under <strong>This site</strong> in the same commit as any content change worth mentioning.</li><li>When the JUCE version in the checkout changes, add a row to the releases table from <code>CHANGE_LIST.md</code> and update the baseline above.</li></ul>',24)])])}const p=t(r,[["render",n]]);export{m as __pageData,p as default};
